sources.original:
def transform(requests):
    cache, values, calls = {}, [], 0
    for request in requests:
        key = request["key"]
        if key not in cache:
            cache[key] = len(key) * request["multiplier"]
            calls += 1
        values.append(cache[key])
    return {"values": values, "calls": calls}

sources.corrected:
def transform(requests):
    cache, values, calls = {}, [], 0
    for request in requests:
        key = (request["key"], request["multiplier"])
        if key not in cache:
            cache[key] = len(request["key"]) * request["multiplier"]
            calls += 1
        values.append(cache[key])
    return {"values": values, "calls": calls}
